import"./chunk-2NFLSA4Y.js";var i={rutherfordScattering:{theory:{concept:"[[Rutherford scattering is the deflection of alpha particles by the electric repulsion of atomic nuclei.]] In 1911 Rutherford concluded from the gold-foil experiment that an atom's positive charge and almost all of its mass are concentrated in a tiny nucleus, tens of thousands of times smaller than the atom."},param:{energy:"Incoming energy",impact:"Distance from the incoming line to the nucleus",nuclearCharge:"Number of protons Z",timeStep:"Animation time step"},hint:{energy:"Kinetic energy far from the nucleus. Higher energy usually means less deflection at the same b.",impact:"b is the signed distance from the incoming asymptote to the nucleus. Zero aims directly at it; a negative value sends the particle below it.",nuclearCharge:"The nucleus has charge +Ze. Gold has Z = 79. A greater Z causes stronger repulsion.",timeStep:"One animation second represents 10 zs of physical time. The orbit is evaluated exactly at each fixed step."},preset:{low:"2 MeV",medium:"5 MeV",high:"10 MeV",headOn:"Head-on",near:"Near: 20 fm",far:"Far: 200 fm",copper:"Copper: 29",silver:"Silver: 47",gold:"Gold: 79"},measure:{time:"Animation time",physicalTime:"Physical flight time",scatteringAngle:"Predicted far-field scattering angle",closest:"Closest distance reached",distance:"Distance to nucleus",deflection:"Current velocity direction",potential:"Electric potential energy",totalEnergy:"Total energy",energyError:"Relative energy error"},view:{impact:"Incoming line and distance b",zoom:"Zoom near the nucleus",positive:"+",alphaSign:"+2e",nucleus:"Nucleus",scale:"One nucleus \xB7 enlarged view \xB7 slowed time",detector:"Detector ring: 600 fm from nucleus",velocity:"v",repulsion:"Repulsion",detected:"Detected"},graph:{energy:"Kinetic and potential energy during scattering",distance:"Approach, closest distance and departure"},section:{experiment:{title:"The gold-foil experiment",text:"In 1909 Hans Geiger and Ernest Marsden, working with Ernest Rutherford, sent alpha particles through thin gold foil and observed scintillations on a screen. Most went nearly straight; rare large deflections could not be explained by a diffuse positive charge."},nucleus:{title:"A small, positive centre",text:"An alpha particle is a helium nucleus with charge +2e. A nucleus with Z protons has charge +Ze. Like charges repel. A very close encounter can reverse the alpha particle without contact with the nucleus."},impact:{title:"Near or far?",text:"The distance b refers to the incoming straight-line asymptote, not to the closest distance on the curved path. [[Large |b| produces a small deflection; small |b| produces a large one.]] Reversing b mirrors the path."},energy:{title:"Where does the energy go?",text:"As the alpha approaches, kinetic energy becomes electric potential energy and it slows down. After turning, it speeds up again. [[Total energy stays constant.]] For a head-on approach, the particle stops momentarily at the closest point."}},formula:{force:"Repulsive Coulomb force; use SI units",angle:"Asymptotic Rutherford angle for b \u2260 0; b = 0 gives 180\xB0",energy:"Conservation of energy in the stationary-nucleus model",closest:"Minimum centre-to-centre distance on the full orbit",headOn:"Head-on turning distance and backscattering"},variable:{e:"Elementary charge: 1.602176634 \xD7 10\u207B\xB9\u2079 C",k:"Coulomb constant: 8.9875517923 \xD7 10\u2079 N\xB7m\xB2/C\xB2"},assumption:{single:"One alpha particle scatters from one nucleus. This is a magnified single encounter, not a statistical simulation of the full foil or repeated collisions.",fixed:"The nucleus is a stationary point charge with infinite effective mass. Recoil is omitted; this approximation is best for heavy nuclei such as gold.",classical:"Motion is classical and nonrelativistic. Electron screening, radiation, quantum effects and strong nuclear forces are omitted; the controls keep the closest approach outside the nuclear-contact region.",boundary:"The orbit starts and is detected at a radius of 600 fm. The predicted angle refers to infinite distance; the current velocity direction at the detector can differ slightly. Initial velocity already includes the field at this finite radius.",time:"Time is slowed: 1 animation second represents 10 zs = 10\u207B\xB2\u2070 physical seconds. The time-step control uses animation seconds.",scale:"Nucleus and alpha symbols are schematic and not to scale. Both coordinate axes use the same scale in femtometres (1 fm = 10\u207B\xB9\u2075 m). The optional camera zoom follows the approach; the detector ring is an ideal observation boundary."},challenge:{back:{title:"Send it back",description:"Complete a run with a final velocity direction at least 170\xB0 from the incoming direction.",hint:"Use a head-on approach: b = 0."},gentle:{title:"Pass with a small deflection",description:"Finish with less than 15\xB0 of deflection.",hint:"Try 5 MeV and b = 200 fm for gold."},large:{title:"Turn through more than 90\xB0",description:"Finish with a deflection between 90\xB0 and 165\xB0.",hint:"Try 5 MeV and b = 10 fm for gold."},below:{title:"Scatter below the nucleus",description:"Finish with a downward velocity direction of more than 30\xB0.",hint:"Use a negative b, such as \u221220 fm, at 5 MeV for gold."},turn:{title:"Turn at 45.5 fm",description:"Complete a run whose closest distance is about 45.5 fm while conserving total energy.",hint:"Aim directly at a gold nucleus with 5 MeV."},energy:{title:"Backscatter without losing total energy",description:"Finish beyond 90\xB0 of deflection with relative energy error below 0.000001%.",hint:"Try a near encounter. Watch kinetic energy turn into potential energy and back."}}}},n={sim:i};export{n as default,i as sim};
